    /// <summary>
    /// MPJ_2147_AssetFutureValue
    /// </summary>
    public void processReport()
    {
        AssetBook           metAssetBook;
        AssetFutureValueTmp metAssetFutureValueTmp = this.getAssetFutureValueTmp();

        next processReport();

        ttsbegin;
        while select forupdate metAssetFutureValueTmp
        {
            metAssetBook = AssetBook::find(metAssetFutureValueTmp.AssetId,metAssetFutureValueTmp.BookId);
            metAssetFutureValueTmp.METServiceLife = metAssetBook.ServiceLife;
            metAssetFutureValueTmp.METCostCenter  = this.getMETCostCenterByDefaultDimension(metAssetBook);
            metAssetFutureValueTmp.update();
        }
        ttscommit;
    }

 /// <summary>
 /// MPJ_2147_AssetFutureValue
 /// </summary>
 /// <param name = "_metAssetBook">
 /// Get AssetBook buffer
 /// </param>
 /// <returns>
 /// Return cost center dimension
/// </returns>
 public Name getMETCostCenterByDefaultDimension(AssetBook _metAssetBook)
 {
   
     Name                METCostCenter;
     METCostCenter   =   METHelper::getDimensionValue(_metAssetBook.DefaultDimension,METConstants::costCenter);
     return              METCostCenter;
 }
